from dataclasses import dataclass, field
# Define your classes and UpdatePosition function here

@dataclass
class OrderedPair:
    x: float = 0.0
    y: float = 0.0

@dataclass
class Body:
    name: str = ""
    position: OrderedPair = field(default_factory=OrderedPair)
    velocity: OrderedPair = field(default_factory=OrderedPair)
    acceleration: OrderedPair = field(default_factory=OrderedPair)


def update_velocity(b: Body, old_acceleration: OrderedPair, time: float) -> OrderedPair:
    new_V = OrderedPair(
        b.velocity.x + 0.5 * (old_acceleration.x + b.acceleration.x) * time,
        b.velocity.y + 0.5 * (old_acceleration.y + b.acceleration.y) * time
    )
    return new_V

import math
from typing import List

# OrderedPair contains two float fields corresponding to
# the x and y coordinates of a point or vector in two-dimensional space.
class OrderedPair:
    def __init__(self, x: float = 0.0, y: float = 0.0):
        self.x = x
        self.y = y

# Boid represents our "bird" object. It contains three
# OrderedPair fields corresponding to its position, velocity, and acceleration.
class Boid:
    def __init__(self):
        self.position = OrderedPair()
        self.velocity = OrderedPair()
        self.acceleration = OrderedPair()

# Sky represents a single time point of the simulation.
# It contains a width parameter indicating the boundary of the sky, as well as a list of Boid objects.
# It also contains the system parameters.
class Sky:
    def __init__(self):
        self.width: float = 0.0
        self.boids: List[Boid] = []
        self.max_boid_speed: float = 0.0  # fastest speed that a boid can fly
        self.proximity: float = 0.0       # used to determine if boids are close enough for forces to apply
        self.separation_factor: float = 0.0
        self.alignment_factor: float = 0.0
        self.cohesion_factor: float = 0.0

def sum_vectors(vectors: List[OrderedPair]) -> OrderedPair:
    return OrderedPair(
    sum(vector.x for vector in vectors),
    sum(vector.y for vector in vectors)   
    )


def limit_speed(vel : OrderedPair, max_speed: float) -> OrderedPair:
    s = (vel.x**2 + vel.y**2) ** 0.5
    if s > max_speed:
        modifier = max_speed/s
        vel.x *= modifier
        vel.y *= modifier
    return vel

def net_acceleration_due_to_cohesion(current_sky: Sky, i: int) -> OrderedPair:
    boid1 = current_sky.boids[i]
    for boid2 in current_sky.boids:
        distance = ((boid2.position.x - boid1.position.x)**2 + (boid2.position.y - boid1.position.y)**2) ** 0.5
        if distance <= current_sky.proximity:
            x_forces = []
            y_forces = []
            x_forces.append(current_sky.cohesion_factor * (boid2.position.x - boid1.position.x) / distance)
            y_forces.append(current_sky.cohesion_factor * (boid2.position.y - boid1.position.y) / distance)
    return OrderedPair(sum(x_forces)/len(x_forces), sum(y_forces)/len(y_forces))

    return vel

def net_acceleration_due_to_cohesion(current_sky: Sky, i: int) -> OrderedPair:
    if not current_sky.boids: return OrderedPair(0.0,0.0)
    boid1 = current_sky.boids[i]
    x_forces = []
    y_forces = []
    for boid2 in current_sky.boids:
        distance = ((boid2.position.x - boid1.position.x)**2 + (boid2.position.y - boid1.position.y)**2) ** 0.5
        if distance < current_sky.proximity and distance != 0:
            x_forces.append(current_sky.cohesion_factor * (boid2.position.x - boid1.position.x) / distance)
            y_forces.append(current_sky.cohesion_factor * (boid2.position.y - boid1.position.y) / distance)
    return OrderedPair(sum(x_forces)/len(x_forces), sum(y_forces)/len(y_forces))

    return vel

def net_acceleration_due_to_cohesion(current_sky: Sky, i: int) -> OrderedPair:
    boid1 = current_sky.boids[i]
    x_forces = []
    y_forces = []
    for boid2 in current_sky.boids:
        distance = ((boid2.position.x - boid1.position.x)**2 + (boid2.position.y - boid1.position.y)**2) ** 0.5
        if distance < current_sky.proximity and distance != 0:
            x_forces.append(current_sky.cohesion_factor * (boid2.position.x - boid1.position.x) / distance)
            y_forces.append(current_sky.cohesion_factor * (boid2.position.y - boid1.position.y) / distance)
    if not x_forces or not y_forces: return OrderedPair(0.0, 0.0)
    return OrderedPair(sum(x_forces)/len(x_forces), sum(y_forces)/len(y_forces))

def net_acceleration_due_to_alignment(current_sky: Sky, i: int) -> OrderedPair:
    boid1 = current_sky.boids[i]
    x_forces = []
    y_forces = []
    for boid2 in current_sky.boids:
        distance = ((boid2.position.x - boid1.position.x)**2 + (boid2.position.y - boid1.position.y)**2) ** 0.5
        if distance < current_sky.proximity and distance != 0:
            x_forces.append(current_sky.alignment_factor * boid2.velocity.x / distance)
            y_forces.append(current_sky.cohesion_factor * boid2.velocity.y / distance)
    if not x_forces or not y_forces: return OrderedPair(0.0, 0.0)
    return OrderedPair(sum(x_forces)/len(x_forces), sum(y_forces)/len(y_forces))
